// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Step 8: Read checklists awaiting the manager": "in1_Step8Readchecklistsawait"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Step 8: Read checklists awaiting the manager";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"goes": (out.person_id ? 'yes' : null), "person_q": (out.person_id ? encodeURIComponent(out.person_id) : null), "record_body": (out.person_id ? JSON.stringify(Object.assign({}, out, { route: undefined, status: 'sent' })) : null), "welcome_body": (out.person_id ? JSON.stringify({ to: out.email, cc: out.manager, subject: 'Welcome: your first week from ' + out.start_date, text: (out.rows || []).map(r => 'Day ' + r.day + ': ' + r.task + ' (' + r.owner + ')').join('\n') }) : null), "done9_body": (out.person_id ? JSON.stringify({ status: 'done', result: 'welcome pack sent: ' + out.how }) : null), "log9_body": (out.person_id ? JSON.stringify({ recipe: 'R9.1', item: out.person_id, decision: 'welcome pack sent (' + out.how + ')', rules: { template_version: out.template_version, source: out.source, how: out.how, items: (out.rows || []).length } }) : null), "welcome_failed_body": (out.person_id ? JSON.stringify({ recipe: 'R9.1', item: out.person_id, reason: 'welcome pack not sent', detail: 'Welcome pack not sent (send error); HR sends it', owner: $('Config').first().json.hr_owner }) : null)});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
const isoToday = () => new Date().toISOString().slice(0, 10);
const day = d => new Date(String(d).slice(0, 10) + 'T00:00:00Z');
const addDays = (d, n) => new Date(day(d).getTime() + n * 86400000).toISOString().slice(0, 10);
// Working days (Monday to Friday) after today, up to and including the date.
function workingDaysUntil(d) {
  const end = day(d); let n = 0;
  for (let x = new Date(day(isoToday()).getTime() + 86400000); x <= end; x = new Date(x.getTime() + 86400000)) {
    if (x.getUTCDay() % 6 !== 0) n++;
  }
  return n;
}

// Step 8 and the failure table: the manager is silent and the start is under 2 working days away,
// so the template's checklist goes.
const cfg = $('Config').first().json;
const waiting = $('Step 8: Read checklists awaiting the manager').first().json.items || [];
return waiting.filter(c => workingDaysUntil(c.start_date) < cfg.approval_working_days).map(c => ({ json: {
  person_id: c.person_id, name: c.name, email: c.email, manager: c.manager, start_date: c.start_date,
  template_version: c.template_version, template_rows: c.template_rows, rows: c.template_rows, source: 'template',
  how: 'template: manager silent' } }));
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };
